INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (455, 1, '언마운트 필수', 'xfs_repair 를 **마운트된 상태** 의 파일시스템에 실행하면 어떻게 될까요?', '경고가 있어요.', NULL, NULL, '[]', 'choice', '["자동으로 읽기 전용으로 바뀌어 안전하게 끝난다", "마운트가 해제된 뒤에 자동으로 진행된다", "결과 파일시스템이 불일치하거나 손상될 수 있다", "아무 영향 없이 정상적으로 수리된다"]', 2, 'xfs_repair 문서는 수리할 파일시스템이 반드시 언마운트되어 있어야 하며, 그렇지 않으면 결과 파일시스템이 불일치하거나 손상될 수 있다고 설명합니다.', NULL, NULL, NULL, '[{"title": "xfs_repair(8) man page", "url": "https://man7.org/linux/man-pages/man8/xfs_repair.8.html"}]'),
  (455, 2, '-n 옵션', '`xfs_repair -n` 은 무엇을 할까요?', '점검만 해요.', NULL, NULL, '[]', 'choice', '["점검 없이 곧바로 모든 수리를 적용한다", "수정 없이 스캔하고 어떤 수리를 할지만 알려 준다", "수리 후 결과를 자동으로 백업한다", "로그를 비우고 다시 마운트한다"]', 1, '문서는 -n 이 no modify 모드로, 파일시스템을 수정하지 않고 스캔해 어떤 수리를 했을지만 알려 준다고 설명합니다. -e 와는 함께 쓸 수 없습니다.', NULL, NULL, NULL, '[{"title": "xfs_repair(8) man page", "url": "https://man7.org/linux/man-pages/man8/xfs_repair.8.html"}]'),
  (455, 3, '-L 위험', '`xfs_repair -L` 의 위험은 무엇일까요?', '로그를 비워요.', NULL, NULL, '[]', 'choice', '["로그를 비워 데이터를 잃을 수 있다", "메모리를 과도하게 써서 시스템이 멈춘다", "레이블이 지워져 마운트가 거부된다", "쿼터 제한값이 모두 초기화된다"]', 0, '문서는 -L 이 로그가 더러워도(메타데이터 변경이 있어도) 로그를 0 으로 채워 강제로 비우며, 파일시스템이 손상되어 보이고 사용자 파일·데이터를 잃을 수 있다고 설명합니다.', NULL, NULL, NULL, '[{"title": "xfs_repair(8) man page", "url": "https://man7.org/linux/man-pages/man8/xfs_repair.8.html"}]'),
  (455, 4, 'dirty log', 'xfs_repair 가 **더러운 로그** 를 발견하면 어떻게 할까요?', '재생하지 못해요.', NULL, NULL, '[]', 'choice', '["로그를 자동으로 재생한 뒤 계속 수리한다", "로그를 무시하고 수리를 끝까지 진행한다", "종료 코드 0 으로 조용히 끝난다", "로그를 재생하지 못하고 종료 코드 2 로 끝난다"]', 3, '문서는 XFS 로그가 같은 CPU 아키텍처의 커널만 재생할 수 있어 xfs_repair 가 더러운 로그를 재생하지 못하고 종료 코드 2 로 끝난다고 설명합니다.', NULL, NULL, NULL, '[{"title": "xfs_repair(8) man page", "url": "https://man7.org/linux/man-pages/man8/xfs_repair.8.html"}]'),
  (455, 5, '로그 재생', '더러운 로그를 **안전하게 재생** 하는 방법으로 문서가 권하는 것은 무엇일까요?', '커널에 맡겨요.', NULL, NULL, '[]', 'choice', '["xfs_repair 를 -n 으로 여러 번 실행한다", "다른 CPU 아키텍처의 머신에서 마운트한다", "같은 종류의 머신에서 마운트했다가 바로 언마운트한다", "레이블을 지우고 다시 만든다"]', 2, '문서는 크래시가 난 것과 같은 종류의 머신에서 마운트했다가 즉시 언마운트해 로그를 재생하라고 하고, 재생 전에 하드웨어가 믿을 만한지 확인하라고 설명합니다.', NULL, NULL, NULL, '[{"title": "xfs_repair(8) man page", "url": "https://man7.org/linux/man-pages/man8/xfs_repair.8.html"}]'),
  (455, 6, '마지막 수단', '마운트가 실패하면 문서는 **-L 사용** 을 어떻게 안내할까요?', '최후예요.', NULL, NULL, '[]', 'choice', '["가장 먼저 시도할 권장 방법으로 안내한다", "최후 수단으로만 쓰고 메타데이터 갱신을 잃는다", "데이터 손실 위험이 전혀 없다고 안내한다", "쿼터를 쓰는 경우에만 쓰라고 안내한다"]', 1, '문서는 마운트가 실패하면 -L 로 로그를 지울 수 있지만 크래시 시점의 모든 메타데이터 갱신을 잃어 큰 손상을 줄 수 있으므로 최후의 수단으로만 쓰라고 설명합니다.', NULL, NULL, NULL, '[{"title": "xfs_repair(8) man page", "url": "https://man7.org/linux/man-pages/man8/xfs_repair.8.html"}]'),
  (455, 7, 'lost+found', '어디에도 연결되지 않은 **고아 파일** 은 어떻게 처리될까요?', '이름은 번호예요.', NULL, NULL, '[]', 'choice', '["lost+found 에 번호 이름으로 연결한다", "휴지통 디렉터리로 옮겨 이름을 유지한다", "발견 즉시 모두 삭제해 버린다", "루트 디렉터리에 원래 이름으로 연결한다"]', 0, '문서는 할당되어 있지만 참조되지 않는 고아 파일·디렉터리를 lost+found 에 넣으며 이름은 inode 번호이고, lost+found 가 없으면 필요할 때 자동으로 만든다고 설명합니다.', NULL, NULL, NULL, '[{"title": "xfs_repair(8) man page", "url": "https://man7.org/linux/man-pages/man8/xfs_repair.8.html"}]'),
  (455, 8, '슈퍼블록 손상', '**기본 슈퍼블록이 심하게 손상** 되었을 때 xfs_repair 는 어떻게 할까요?', '보조가 있어요.', NULL, NULL, '[]', 'choice', '["즉시 중단하고 아무것도 수정하지 않는다", "손상된 기본 슈퍼블록을 그대로 믿고 쓴다", "파일시스템을 비우고 새로 만든다", "보조 슈퍼블록으로 기본을 새로 만든다"]', 3, '문서는 XFS 에 기본·보조 슈퍼블록이 있으며, 기본이 너무 손상되면 파일시스템을 스캔해 보조 슈퍼블록 몇 개를 찾아 검증하고 기본 슈퍼블록을 생성한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "xfs_repair(8) man page", "url": "https://man7.org/linux/man-pages/man8/xfs_repair.8.html"}]'),
  (455, 9, '디스크 오류', '디스크 드라이브 고장이 원인일 때 xfs_repair 전에 **문서가 권하는 것** 은 무엇일까요?', '복사부터예요.', NULL, NULL, '[]', 'choice', '["xfs_repair 를 여러 번 반복 실행한다", "-L 로 로그부터 강제로 비운다", "dd 로 좋은 디스크에 복사해 둔다", "마운트한 채로 xfs_repair 를 실행한다"]', 2, '문서는 xfs_repair 가 대부분의 디스크 I/O 오류에서 중단되므로 모든 블록을 읽고 쓸 수 있게 한 뒤 써야 하며, 한 방법으로 dd 로 좋은 디스크에 복사하는 것을 든다고 설명합니다.', NULL, NULL, NULL, '[{"title": "xfs_repair(8) man page", "url": "https://man7.org/linux/man-pages/man8/xfs_repair.8.html"}]'),
  (455, 10, '수정 없이 점검', '파일시스템을 **수정하지 않고** 점검만 하는 옵션입니다. 빈칸을 채우세요.', 'no-modify 의 n 이에요.', NULL, NULL, '[]', 'fill', '["-n", "-L", "-d", "-e"]', NULL, '-n 은 수정 없이 스캔합니다. -L 은 로그 강제 비우기, -d 는 읽기 전용 마운트 상태 수리, -e 는 종료 코드 4 보고입니다.', '[0]', 'xfs_repair {0} /dev/sdb1', NULL, '[{"title": "xfs_repair(8) man page", "url": "https://man7.org/linux/man-pages/man8/xfs_repair.8.html"}]'),
  (455, 11, '로그 강제 비우기', '로그를 **강제로 비우는** 마지막 수단 옵션입니다. 빈칸을 채우세요.', '대문자 L 이에요.', NULL, NULL, '[]', 'fill', '["-L", "-n", "-P", "-v"]', NULL, '-L 은 더러운 로그도 0 으로 채워 비웁니다. -n 은 점검, -P 는 프리페치 끄기, -v 는 자세한 출력입니다.', '[0]', 'xfs_repair {0} /dev/sdb1', NULL, '[{"title": "xfs_repair(8) man page", "url": "https://man7.org/linux/man-pages/man8/xfs_repair.8.html"}]'),
  (455, 12, 'XFS 수리', 'XFS 점검·수리의 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '언마운트 → 점검 → 로그 재생 → 수리예요.', NULL, NULL, '[]', 'order', '["`umount` 로 파일시스템을 언마운트한다", "`xfs_repair -n` 으로 수정 없이 점검한다", "로그가 더러우면 마운트했다가 바로 언마운트해 재생한다", "`xfs_repair` 를 실행해 수리한다"]', NULL, '문서의 언마운트 요구, -n, DIRTY LOGS 설명을 이은 일반 절차입니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "xfs_repair(8) man page", "url": "https://man7.org/linux/man-pages/man8/xfs_repair.8.html"}]');
